    kalkFoodcostLblKost: 'Ingredient cost per dish',
    kalkFoodcostModeLbl: 'I want to enter',
    kalkFoodcostModeFc: 'Target food cost %',
    kalkFoodcostModeMeny: 'Menu price',
    kalkFoodcostValLblFc: 'Target food cost',
    kalkFoodcostValHintFc: 'Typically 28–35 % for hot dishes in a restaurant.',
    kalkFoodcostValLblMeny: 'Menu price incl. VAT',
    kalkFoodcostValHintMeny: 'The price the guest pays — we work out the food cost from it.',
    kalkFoodcostMvaLbl: 'VAT rate',
    kalkFoodcostMva25: '25 % · dining in',
